import{_ as t,o as s,c as o,a5 as i}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-15-delete-workspace/report3_spec.md","filePath":"feature/agency-workspace/3-4-15-delete-workspace/report3_spec.md"}'),n={name:"feature/agency-workspace/3-4-15-delete-workspace/report3_spec.md"};function r(a,e,l,c,p,d){return s(),o("div",null,[...e[0]||(e[0]=[i("<p><strong>3.4.15 Delete Workspace</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an Agency owner confirms deletion of a Workspace by opening Workspace settings and typing the Workspace name in the danger-zone confirmation dialog.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: Agency OWNER.</li><li><strong>Purpose</strong>: Lets the owner remove a Workspace that is no longer used while keeping it recoverable for 30 days.</li><li><strong>Interface</strong>: A &quot;Danger Zone&quot; block inside Workspace settings, visible only when the caller can manage, with a Delete button that opens a confirmation dialog requiring the user to type the Workspace name before the destructive action is enabled. There is currently no Restore entry point in the frontend - restore exists only as a backend endpoint.</li><li><strong>Data Processing</strong>: The system marks the Workspace as soft-deleted (status = SOFT_DELETED, deletedAt = now()); restoring within 30 days reverses this. Deleting only flips the Workspace&#39;s own status/timestamp fields - it does not cascade to Task/Campaign/Material records; those remain ACTIVE and are not automatically hidden. Access is not revoked mid-session either.</li></ul><p><strong>Screen Layout</strong></p><p>Figure - Delete Workspace Dialog:</p><ul><li>A destructive confirmation dialog opened from the Danger Zone in Workspace settings, visible to the owner only.</li><li>The dialog requires the user to type the Workspace name before &quot;Confirm Delete&quot; is enabled; a Cancel button closes it without action.</li><li>On success, a success toast is shown and the user is navigated to the Workspace list; on failure, an error toast is shown.</li><li>No restore screen exists in the frontend today - the restore capability is backend-only.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: the Workspace identifier; the caller&#39;s authenticated identity; the typed Workspace name confirming the action.</li><li><strong>Input optional</strong>: none.</li><li><strong>System data</strong>: the Workspace record with its status and deletion timestamp; the deletion window allowed for restoration.</li><li><strong>Output</strong>: confirmation that the Workspace has been soft-deleted; on restore, the restored Workspace profile.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-26</strong>: Delete workspace is OWNER-only, implemented here as Agency OWNER. Soft-delete vs hard-delete, and the interaction with an active paid subscription, remain TBD - the implemented code only ever soft-deletes.</li><li>A caller who is not the Agency OWNER, including the Workspace MANAGER -&gt; 403 FORBIDDEN.</li><li>Restoring later than 30 days after deletion -&gt; 410 RESTORE_WINDOW_EXPIRED.</li><li>Restoring a Workspace whose status is not SOFT_DELETED -&gt; 400 WORKSPACE_NOT_DELETED.</li><li>Known gap: deleteWorkspace only sets the Workspace&#39;s own status/deletedAt - there is no cascade write to Task/Campaign/Material records. Member/Client access is not revoked mid-session; the deleted Workspace simply no longer appears in the Workspace list. If cascading to inactive is required, it needs new code.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>The typed Workspace name must match the Workspace being deleted before the action is enabled.</li><li>The caller must be the Agency OWNER; otherwise 403 FORBIDDEN, toast <strong>MSG39</strong>.</li><li>The Workspace must exist; otherwise 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>.</li><li>The caller must belong to the Workspace&#39;s Agency; otherwise toast <strong>MSG40</strong>.</li><li>Restore is allowed only when the Workspace&#39;s status is SOFT_DELETED and within 30 days of the deletion timestamp.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Owner opens Workspace settings and chooses Delete in the Danger Zone.</li><li>Dialog asks the owner to type the Workspace name to confirm; the Confirm Delete button stays disabled until the typed value matches.</li><li>System confirms the caller is the Agency OWNER; otherwise the request fails with 403 FORBIDDEN.</li><li>System marks the Workspace as soft-deleted and records the deletion timestamp.</li><li>Task/Campaign/Material records inside the Workspace are left as-is - no cascade occurs.</li><li>The Workspace disappears from active listings; success toast shown, user navigated to the Workspace list. It becomes restorable for 30 days via the backend endpoint only.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: Caller is not the Agency OWNER, even when they manage the Workspace -&gt; 403 FORBIDDEN, toast <strong>MSG39</strong>. 3.a2: The caller returns to Workspace settings without deleting.</li><li>3.b1: The Workspace does not exist -&gt; 404 WORKSPACE_NOT_FOUND, toast <strong>MSG38</strong>. 3.b2: The caller returns to the Workspace list.</li><li>3.c1: The caller does not belong to this Workspace&#39;s Agency -&gt; toast <strong>MSG40</strong>. 3.c2: The caller is returned to their own Workspace list.</li><li>Restoring a Workspace that is not currently soft-deleted -&gt; 400 WORKSPACE_NOT_DELETED.</li><li>Restoring after the 30-day window -&gt; 410 RESTORE_WINDOW_EXPIRED.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>The Workspace is marked soft-deleted and is hidden from active listings.</li><li>The Workspace&#39;s Task/Campaign/Material records are unaffected - no cascade exists today.</li><li>The Workspace remains restorable for 30 days via the backend restore endpoint (no FE screen currently exposes this).</li></ul>",14)])])}const u=t(n,[["render",r]]);export{h as __pageData,u as default};
